"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[8639],{38639:a=>{a.exports=JSON.parse('{"meta":{"title":"Niyyah: Jadikan Niat Langkah Kecil yang Istiqamah - iMuslim Life","description":"Niyyah mengubah niat menjadi rencana 7 hari yang terikat pada waktu salatmu, dan Gema Al-Qur\'an menemukan ayat yang telah ditinjau ulama untuk isi hatimu. Gratis, tanpa iklan."},"periods":{"fajr":"Subuh","dhuhr":"Zuhur","asr":"Asar","maghrib":"Magrib","isha":"Isya"},"hero":{"eyebrow":"Niyyah","h1":"Jadikan niat sebagai langkah <g>kecil yang istiqamah</g>.","lede":"Lima pertanyaan lembut menjadi rencana tujuh hari yang terjalin dengan salat yang sudah kamu kerjakan. Dan saat hatimu berat, Gema Al-Qur\'an menemukan ayat-ayat yang menyapanya.","begin":"Mulai, bismillah","tryEchoes":"Coba Gema Al-Qur\'an","facts":"Gratis \xb7 Tanpa iklan \xb7 Ditinjau ulama \xb7 Berjalan di browsermu","scroll":"Gulir: satu hari, dari Subuh hingga Isya","alt":"Niyyah: lengkung mihrab dengan Basmalah di bawah langit malam"},"hadith":{"text":"\u201cSesungguhnya amal itu tergantung niatnya.\u201d","src":"Shahih al-Bukhari 1 \xb7 Shahih Muslim 1907"},"steps":[{"t":"Niat","d":"Pilih apa yang ingin kamu tumbuhkan: sabar, dekat dengan Al-Qur\'an, syukur, lemah lembut di rumah."},{"t":"Amal","d":"Satu langkah kecil, dua sampai lima belas menit. Cukup kecil untuk dijaga di hari tersulitmu."},{"t":"Waktu","d":"Terikat pada salat yang sudah kamu kerjakan, sesuai waktu salatmu sendiri, jadi ikut berubah mengikuti musim."},{"t":"Renungan","d":"Tinjauan lembut di hari ketiga dan ketujuh. Waktunya kurang pas? Terlalu berat? Bisa disesuaikan dalam hitungan detik."}],"effortNote":"Menyelesaikan rutinitas adalah ikhtiar kita. Penerimaan dan hasilnya milik Allah. Rencana ini alat bantu, bukan ukuran imanmu.","try":{"eyebrow":"Gema Al-Qur\'an \xb7 coba sekarang","h2":"Apa yang ada di <e>hatimu</e>?","lede":"Tulis satu kalimat tentang yang sedang kamu hadapi, dalam bahasa Inggris, Urdu, Urdu Latin, atau Arab. Niyyah menjawab dengan ayat dari indeks yang ditinjau ulama dan satu pertanyaan untuk direnungkan. Tanpa login. Tidak ada yang kamu ketik disimpan.","inputLabel":"Ceritakan keadaanmu","listening":"Mendengarkan\u2026","find":"Cari ayat","failed":"Gema Al-Qur\'an tidak dapat dihubungi saat ini. Ia ada di <a>alexa.imuslimlife.com/niyyah</a>, silakan coba di sana.","crisisH":"Mohon hubungi seseorang sekarang.","crisisP":"Yang kamu ceritakan terdengar serius, dan kamu layak mendapat dukungan nyata dari seseorang.","rulingEyebrow":"Ini perlu ulama","rulingH":"Pertanyaan hukum perlu dijawab orang yang berilmu.","rulingP":"Niyyah tidak pernah memberi fatwa. Imam yang mengenal keadaanmu dapat menjawab dengan tepat.","none":"Belum ada yang cocok. Coba tambahkan beberapa kata tentang perasaanmu atau yang kamu hadapi.","surah":"Surah","tafsir":"Tafsir","plan":"Jadikan rencana 7 hari","missThanks":"Terima kasih, itu membantu kami memperbaiki. Coba ceritakan dengan kata lain.","miss":"Bukan itu maksudku","shared":"Terbagikan, terima kasih. Ini membantu memperbaiki Gema Al-Qur\'an.","share":"Bagikan pertanyaan ini (tanpa namamu) untuk membantu memperbaiki Gema Al-Qur\'an.","example":"Contoh","exampleQ":"Kapan terakhir kali zikir kepada Allah membuatmu tenang?","exampleSrc":"Ar-Ra\'d 13:28 \xb7 Terjemahan makna: Kementerian Agama RI. Teks Arab: Tanzil Utsmani.","examples":["I keep losing my temper with my kids","mujhe bohat ghussa aata hai","I feel guilty, will Allah forgive me?","My father passed away and it feels heavy","I\u2019m anxious about money and the future"],"placeholder":"For example: I get impatient with my children in the evenings"},"ayah":{"en":"(yaitu) orang-orang yang beriman dan hati mereka manjadi tenteram dengan mengingat Allah. Ingatlah, hanya dengan mengingati Allah-lah hati menjadi tenteram.","src":"Ar-Ra\'d 13:28 \xb7 Terjemahan makna: Kementerian Agama RI"},"week":{"eyebrow":"Pekanmu","h2":"Setiap hari kamu hadir, <e>sekuntum mawar mekar</e>.","lede":"Tak ada rentetan yang putus, tak ada rasa bersalah. Hari yang terlewat tetap jadi kuncup, dan rencana berlanjut besok. Langit berubah mengikuti waktu salatmu, dari merah muda Subuh hingga bintang Isya.","label":"Sepekan mawar: lima hari mekar","shots":["Hari ini, saat Isya","Rencana 7 harimu","Hari yang sama, saat Zuhur"]},"care":{"eyebrow":"Dibuat dengan cermat","h2":"Tepercaya <e>sejak rancangannya</e>.","items":[{"t":"Ditinjau ulama","d":"Setiap ayat, amal kecil, dan pertanyaan ditinjau dan disetujui sebelum ada yang melihatnya."},{"t":"Bukan fatwa","d":"Pertanyaan hukum diarahkan dengan lembut kepada ulama yang berkompeten. Niyyah tidak pernah memutuskan hukum."},{"t":"Tak ada yang dikarang","d":"Tidak ada AI yang menulis teks agama di sini. Ayatnya adalah Al-Qur\'an itu sendiri, dengan terjemahan yang jelas sumbernya."},{"t":"Aman","d":"Kata-kata tentang bahaya memunculkan layanan bantuan lebih dulu, bukan ayat."},{"t":"Pribadi","d":"Catatanmu hanya milikmu. Hapus semuanya dengan satu ketukan."},{"t":"Gratis selamanya","d":"Tanpa iklan, tanpa langganan. Sedekah jariyah, insya Allah."}]},"faq":{"eyebrow":"Pertanyaan","h2":"Baik untuk <e>diketahui</e>.","items":[{"q":"Apa arti \u201cNiyyah\u201d?","a":"Niyyah (\u0646\u0650\u064a\u064e\u0651\u0629) berarti niat. \u201cSesungguhnya amal itu tergantung niatnya\u201d (Shahih al-Bukhari 1). Niyyah membantu niat menjadi amal kecil yang istiqamah."},{"q":"Apakah perlu akun?","a":"Tidak perlu akun untuk mencoba Gema Al-Qur\'an. Untuk menyimpan rencana, menandai hari-hari kamu hadir, dan menyimpan ayat, masuk dengan Amazon, sama seperti Muslim Companion for Alexa."},{"q":"Bahasa apa yang dipahami?","a":"Inggris, Urdu, Urdu Latin (seperti \u201cmujhe bohat ghussa aata hai\u201d), dan Arab. Ayat ditampilkan dalam bahasa Arab dengan terjemahan Inggris atau Urdu."},{"q":"Apakah ini pengganti ulama atau konselor?","a":"Tidak. Niyyah menawarkan ayat untuk direnungkan dan langkah kecil untuk dijalankan. Untuk hukum, tanyakan kepada ulama yang berkompeten; di masa sulit, hubungi orang yang kamu percaya atau layanan bantuan."},{"q":"Di mana bisa digunakan?","a":"Di browser apa pun di ponsel, tablet, atau komputer, di alexa.imuslimlife.com/niyyah."}]},"final":{"h2":"Mulailah dengan langkah <g>kecil</g>.","lede":"Rencana pertamamu hanya butuh semenit. Semoga Allah memudahkannya dan menerimanya darimu.","alexa":"Muslim Companion for Alexa"}}')}}]);